///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/compfinance/financialinfo.do",
        ref: "dma_fnDownloadReq",
        target: "dlt_stdIndustry=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/compfinance/financialinfo.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearchInit(true);
};

/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @param {String} isFlag isFlag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function (isFlag) {
    if (isFlag === false) {
        $c.util.getComponent("dma_fnDownloadReq").set("isfirst", "false");
    }
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    if (($c.util.getComponent('slc_industry').getValue() == null ? '' : String($c.util.getComponent('slc_industry').getValue())) === '') {
        await $c.win.alert("업종을 선택해 주세요.");
        return false;
    }
    if ($c.util.getComponent('slc_industry').getValue() === '03') {
        await $c.win.alert("죄송합니다. 제조업의 하위 업종을 선택해 주세요.");
        return false;
    }
    if ($c.util.getComponent("ipt_currentPageSize").getValue() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $c.util.getComponent("ipt_currentPageSize").getValue());
    }
    const titleofaccnt = scwin.makeTitleOfAccountParamString();
    $c.util.getComponent('ipt_titleofaccnt').setValue(titleofaccnt);
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchFinancialInfoInTheIndustry");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "list");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack1
 * @description fn Search Call Back1 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack1 = function (data) {
    $("#mainContents").empty().append(data);
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnLegendTooltip( " ') */
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $c.util.getComponent("ipt_currentPageSize").getValue());
    await scwin.fnSearch();
};

/**
 * @method
 * @name makeTitleOfAccountParamString
 * @description make Title Of Account Param String 처리
 * @returns {void}
 * @hidden N
 */
scwin.makeTitleOfAccountParamString = function () {
    let paramString = "";
    let flag = false;
    paramString = "";
    const finsearchtype = $c.util.getComponent('ipt_finsearchtype').getValue();
    if (finsearchtype === "finstat") {
        for (let i = 0; i < scwin.finstat.length; i++) {
            flag = scwin.checkChkBoxStatus(scwin.finstat[i]);
            if (flag) {
                paramString += scwin.finstat[i];
                if (i !== (scwin.finstat.length - 1)) {
                    paramString += "|";
                }
            }
        }
    } else {
        if (finsearchtype === "finrate") {
            for (let i = 0; i < scwin.finrate.length; i++) {
                flag = scwin.checkChkBoxStatus(scwin.finrate[i]);
                if (flag) {
                    paramString += scwin.finrate[i];
                    if (i !== (scwin.finrate.length - 1)) {
                        paramString += "|";
                    }
                }
            }
        }
    }
    return paramString;
};

/**
 * @method
 * @name checkChkBoxStatus
 * @description check Chk Box Status 처리
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.checkChkBoxStatus = function (id) {
    return $("#" + id).is(":checked");
};

/**
 * @method
 * @name changeTitleOfAccountPanel
 * @description change Title Of Account Panel 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeTitleOfAccountPanel = function () {
    const val = $c.util.getComponent('slc_fininfotype').getValue();
    if (val === "finstat") {
        scwin.title_of_account1.setStyle("display", "");
        scwin.title_of_account2.setStyle("display", "none");
        $c.util.getComponent('ipt_finsearchtype').setValue("finstat");
        $c.util.getComponent("dma_fnDownloadReq").set("orderMode", scwin.finstat[0]);
        $c.util.getComponent("dma_fnDownloadReq").set("orderStat", 'D');
    } else {
        if (val === "finrate") {
            scwin.title_of_account1.setStyle("display", "none");
            scwin.title_of_account2.setStyle("display", "");
            $c.util.getComponent('ipt_finsearchtype').setValue("finrate");
            $c.util.getComponent("dma_fnDownloadReq").set("orderMode", scwin.finrate[0]);
            $c.util.getComponent("dma_fnDownloadReq").set("orderStat", 'D');
        }
    }
};

/**
 * @method
 * @name changeAllCheckState
 * @description change All Check State 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeAllCheckState = function () {
    const val = $c.util.getComponent('slc_fininfotype').getValue();
    if (val === "finstat") {
        for (let i = 0; i < scwin.finstat.length; i++) {
            if ($("#ipt_chAll1").is(":checked")) {
                $("#" + scwin.finstat[i]).attr("checked", true);
            } else {
                $("#" + scwin.finstat[i]).attr("checked", false);
            }
        }
    } else {
        if (val === "finrate") {
            for (let i = 0; i < scwin.finrate.length; i++) {
                if ($("#ipt_chAll2").is(":checked")) {
                    $("#" + scwin.finrate[i]).attr("checked", true);
                } else {
                    $("#" + scwin.finrate[i]).attr("checked", false);
                }
            }
        }
    }
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    const titleofaccnt = scwin.makeTitleOfAccountParamString();
    $c.util.getComponent('ipt_titleofaccnt').setValue(titleofaccnt);
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "download_industry");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "download_industry");
    await scwin.tx_fnDownload();
};
